.poppins-thin  {

  font-family: "Poppins", sans-serif;

  font-weight: 100;

  font-style: normal;

}

.poppins-extralight  {

  font-family: "Poppins", sans-serif;

  font-weight: 200;

  font-style: normal;

}

.poppins-light  {

  font-family: "Poppins", sans-serif;

  font-weight: 300;

  font-style: normal;

}

.poppins-regular  {

  font-family: "Poppins", sans-serif;

  font-weight: 400;

  font-style: normal;

}

.kaisei-decol-regular  {

  font-family: "Kaisei Decol", serif;

  font-weight: 400;

  font-style: normal;

}

*  {

  margin: 0;

  padding: 0;

}

body  {

  font-family: "Poppins", sans-serif;

  line-height: 1.6;

  color: #000000;

}

a  {

  text-decoration: none;

  color: inherit;

}

img  {

  max-width: 60%;

  height: auto;

}

header  {

  background: #ffffff;

  padding: 1rem 2rem;

  display: flex;

  justify-content: space-between;

  align-items: center;

  /* position: sticky;
  */
  top: 0;

  z-index: 100;

  box-shadow: 0 2px 5px rgba(0, 0, 0, 0.1);

}

header .logo  {

  font-family: "Kaisei Decol", serif;

  font-size: 1.8rem;

  font-weight: 400;

}

.active {

  color:#AB864C;

}

#act  {

  color: #AB864C;

}

header nav ul  {

  display: flex;

  list-style: none;

  gap: 2rem;

}

header nav ul li a  {

  font-weight: 500;

  transition: color 0.3s;

}

header nav ul li a:hover  {

  color: #AB864C;

}

.hero  {

  background: url("assets/images/haute-couture-2.jpg") no-repeat center;

  background-size: cover;

  height: 60vh;

  display: flex;

  align-items: center;

  justify-content: center;

  text-align: center;

  color: #ffffff;

  position: relative;

}

.hero::before  {

  content: "";

  position: absolute;

  top: 0;

  left: 0;

  width: 100%;

  height: 100%;

  background: rgba(0, 0, 0, 0.4);

}

.hero h1  {

  font-family: "Kaisei Decol", serif;

  background: rgba(255, 255, 255, 0.7);

  width: 400px;

  height: 120px;

  color: #120404;

  z-index: 1;

  text-shadow: 2px 2px 4px rgba(0, 0, 0, 0.5);

}

.image  {

  width: 0%;

  height: 40%;

  margin: auto;

}

.quote  {

  padding: 3rem 2rem;

  text-align: center;

  margin: auto;

  background: #ffffff;

  font-weight: 700;

}

.quote blockquote  {

  font-family: "Kaisei Decol", serif;

  /* font-weight: 700;
  */
  font-size: 1.2rem;

  width: 100%;

  /* font-style: italic;
  */
  margin-bottom: 1rem;

}

.quote cite  {

  display: block;

  font-weight: 500;

  margin: auto;

}

.description  {

  max-width: 800px;

  margin: 2rem auto;

  padding: 2rem;

  border: 1px solid #000000;

  text-align: center;

}

.signature  {

  background: #AB864C;

  padding: 3rem 2rem;

  color: #ffffff;

  text-align: center;

}

.signature h2  {

  font-family: "Kaisei Decol", serif;

  margin-bottom: 5rem;

}

.signature .pastries  {

  display: flex;

  justify-content: center;

  gap: 2rem;

  flex-wrap: wrap;

}

.signature .pastries .pastry  {

  background: rgba(255, 255, 255, 0.0);

  padding: 1.5rem;

  border-radius: 0px;

  max-width: 300px;

}

.signature .pastries .pastry img  {

  border-radius: 0px;

  margin-bottom: 1rem;

}

.signature .pastries .pastry h3  {

  margin: 1rem 0;

  font-family: "Kaisei Decol", serif;

}

.signature .pastries .pastry p  {

  font-size: 0.9rem;

}

.signature .btn  {

  display: inline-block;

  margin-top: 2rem;

  padding: 0.75rem 1.5rem;

  background: #AB864C;

  color: #ffffff;

  border: 1px solid #ffffff;

  transition: all 0.3s;

}

.btn  {

  margin-top: 120px;

}

.signature .btn:hover  {

  background: transparent;

  color: #ffffff;

}

.history  {

  padding: 3rem 2rem;

  display: flex;

}

.history .image  {

  min-width: 300px;

  margin: 20;

}

.history .image img  {

  border-radius: 50%;

  box-shadow: 0 0 20px rgba(0, 0, 0, 0.1);

}

img  {

  max-width: 100%;

  height: auto;

}

.image  {

  margin: 20px 10px 10px 10px;

}

.history .text  {

  min-width:120px;

  margin: left;

}

.history .text h2  {

  font-family: "Kaisei Decol", serif;

  margin-bottom: 1rem;

}

.history .text p  {

  margin: 20px auto;

  flex-wrap: wrap;

}

.history .text .btn  {

  padding: 0.75rem 1.5rem;

  background: #AB864C;

  color: #ffffff;

  border: none;

  margin: 60px 0 -20px 0;

  cursor: pointer;

}

hr {

  border-top: 1px solid rgba(255, 255, 255, 0.2);

}

.event  {

  padding: 3rem 2rem;

  background: #ffffff;

  display: flex;

  gap: 2rem;

  flex-wrap: wrap;

}

.event .text  {

  flex: 1;

  min-width: 300px;

}

.event .text h2  {

  font-family: "Kaisei Decol", serif;

  margin-bottom: 1rem;

}

.event .text p  {

  margin-bottom: 1rem;

}

.event form  {

  flex: 1;

  min-width: 300px;

}

.event form .form-group  {

  margin-bottom: 1rem;

}

.event form .form-group label  {

  display: block;

  margin-bottom: 0.5rem;

}

.event form .form-group input, .event form .form-group textarea  {

  width: 100%;

  padding: 0.5rem;

  border: 1px solid #ccc;

  border-radius: 5px;

}

.event form .checkbox  {

  display: flex;

  align-items: center;

  gap: 0.5rem;

  margin: 1rem 0;

}

.event form .btn  {

  width: 100%;

  padding: 0.75rem;

  background: #AB864C;

  color: #ffffff;

  border: none;

  border-radius: 0px;

  cursor: pointer;

}

.map  {

  background: #AB864C;

  padding: 2rem 0;

  text-align: center;

  color: #ffffff;

}

.map h2  {

  font-family: "Kaisei Decol", serif;

  margin-bottom: 1rem;

}

.map p  {

  margin-bottom: 1rem;

}

.map iframe  {

  width: 100%;

  height: 400px;

  border: none;

  border-radius: 0px;

}

footer  {

  background: #000000;

  color: #ffffff;

  padding: 2rem;

  display: flex;

  flex-wrap: wrap;

  gap: 2rem;

  justify-content: space-between;

}

.footer-content  {

  display: flex;

  justify-content: space-between;

  align-items: flex-start;

  flex-wrap: wrap;

  gap: 2rem;

  width: 100%;

}

footer .logo  {

  font-family: "Kaisei Decol", serif;

  font-size: 0.6rem;

}

footer .links  {

  display: flex;

  flex-direction: column;

  gap: 0.1rem;

  align-content: baseline;

}

footer .links a  {

  color: #ffffff;

}

footer .links a:hover  {

  color: #AB864C;

}

footer .contact  {

  display: flex;

  flex-direction: column;

  gap: 0.2rem;

}

footer .contact .phone  {

  font-weight: bold;

}

footer .contact .address  {

  white-space: pre-line;

}

footer .hours  {

  display: flex;

  flex-direction: column;

  gap: 0.3rem;

}

footer .hours strong  {

  font-weight: bold;

}

footer .social  {

  display: flex;

  flex-direction: column;

  gap: 0.3rem;

}

footer .social h4  {

  margin-bottom: 0.3rem;

}

footer .social .icons  {

  display: flex;

  gap: 0.8rem;

}

footer .social .icons a  {

  font-size: 1rem;

  color: #ffffff;

}

footer .social .icons a:hover  {

  color: #AB864C;

}

footer .legal  {

  width: 100%;

  text-align: center;

  margin-top: 1rem;

  border-top: 1px solid rgba(255, 255, 255, 0.2);

  padding-top: 1rem;

  font-size: 0.8rem;

}

footer .legal a  {

  color: #ffffff;

  margin: 0 1rem;

}

footer .legal a:hover  {

  color: #AB864C;

}

@media (max-width: 768px)  {

  header  {

    flex-direction: column;

    gap: 1rem;

  }

  header nav ul  {

    flex-direction: column;

    align-items: center;

    gap: 1rem;

  }

  .hero h1  {

    font-size: 2rem;

  }

  .signature .pastries  {

    flex-direction: column;

    align-items: center;

  }

  .history  {

    flex-direction: column;

  }

  .event  {

    flex-direction: column;

  }

  footer  {

    flex-direction: column;

    align-items: center;

    text-align: center;

  }

  .footer-content  {

    flex-direction: column;

    align-items: center;

  }

  footer .social .icons  {

    justify-content: center;

  }

}

@media (max-width: 335px)  {

  body  {

    font-family: "Poppins", sans-serif;

  }

  header nav ul li a  {

    font-weight: 300;

    transition: color 0.3s;

  }

  header nav ul  {

    flex-direction: column;

    list-style: none;

    gap: .1rem;

  }

  .hero h1  {

    font-family: "Kaisei Decol", serif;

    background: rgba(255, 255, 255, 0.7);

    width: 715px;

    height: 120px;

    color: #120404;

    z-index: 1;

    text-shadow: 2px 2px 4px rgba(0, 0, 0, 0.5);

  }

  .signature .btn  {

    display: inline-block;

    margin-top: 0rem;

    padding: 0.55rem 1rem;

    background: #AB864C;

    color: #ffffff;

    border: 1px solid #ffffff;

    transition: all 0.3s;

  }

  .quote blockquote  {

    font-family: "Kaisei Decol", serif;

    font-size: 1rem;

    font-style: italic;

    margin-bottom: 1rem;

  }

  .description  {

    max-width: 704px;

    margin: 1rem auto;

    padding: 1rem;

    border: 1px solid #000000;

    text-align: center;

  }

  footer .legal  {

    width: 100%;

    text-align: center;

    margin-top: -1rem;

    border-top: 3px solid rgba(239, 229, 229, 0.2);

    padding-top: 2rem;

    font-size: .9rem;

    font-weight: 300;

  }

  .event form .btn  {

    width: 90%;

    padding: 0.75rem;

    background: #AB864C;

    color: #ffffff;

    border: none;

    border-radius: 0px;

    cursor: pointer;

  }

}

